 drivers/usb/cdns3/cdnsp-gadget.h |  31 +++++++
 drivers/usb/cdns3/cdnsp-mem.c    |  98 ++++++++-------------
 drivers/usb/cdns3/cdnsp-ring.c   |   5 ++
 4 files changed, 248 insertions(+), 66 deletions(-)

